<div class="bg-white rounded-xl shadow p-6 mb-6"><h2 class="text-lg font-semibold mb-4">Barang Dikembalikan</h2><?php $canProcess = $pending && $role === 'ADMIN'; if ($canProcess): ?><form method="POST" action="<?=url('/returns/process')?>"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_token']??'')?>"><input type="hidden" name="id" value="<?=$return['id']?>"><?php endif; ?><div class="overflow-x-auto"><table class="w-full"><thead class="bg-gray-50"><tr><th class="p-3 text-left">Barang</th><th class="p-3 text-center">Jumlah</th><th class="p-3 text-left">Serial Number</th><th class="p-3 text-left">Kondisi</th></tr></thead><tbody><?php foreach($items as $it):?><tr class="border-t"><td class="p-3 font-medium"><?=htmlspecialchars($it['nama']??$it['manual_name']??'Barang Manual')?></td><td class="p-3 text-center"><?=$it['quantity']?></td><td class="p-3"><?=$it['serial_number']?htmlspecialchars($it['serial_number']):'-'?></td><td class="p-3"><?php if($canProcess):?><select name="conditions[<?=$it['id']?>]" class="border rounded-lg px-2 py-2"><option value="GOOD">Baik</option><option value="BROKEN">Rusak</option></select><?php else: ?><span class="font-semibold"><?=htmlspecialchars($it['condition_status'])?></span><?php endif;?></td></tr><?php endforeach;if(empty($items)):?><tr><td colspan="4" class="p-8 text-center text-gray-500">Tidak ada barang.</td></tr><?php endif;?></tbody></table></div><?php if($canProcess):?><div class="flex justify-end mt-5"><button class="bg-green-600 text-white px-5 py-2 rounded-lg font-semibold">Proses Pengembalian</button></div></form><?php endif;?></div><?php require __DIR__.'/../../components/audit_timeline.php';?></div><?php $content=ob_get_clean();require __DIR__.'/../../layouts/app.php'; ?>